    justify-content: center;
}

main {
    max-width: 600px;
    width: 100%;
}

h1 {
    color: var(--accent-color);
    text-align: center;
    margin-bottom: 2rem;
}

.form-field {
    background-color: var(--surface-color);
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1.5rem;
    border: 2px solid var(--border-color);
}

fieldset {
    border: none;
    margin: 0;
    padding: 0;
}

legend {
    font-size: 1.2rem;
