    color: var(--error-color);
    font-size: 0.9rem;
    font-weight: bold;
    margin-top: 1rem;
}

.option {
    display: flex;
    align-items: center;
    margin-bottom: 0.75rem;
}

.option input[type="checkbox"] {
    width: 24px;
    height: 24px;
    margin-right: 12px;
    cursor: pointer;
    accent-color: var(--accent-color);
    border: 2px solid var(--border-color);
    border-radius: 4px;
}

.option label {
    cursor: pointer;
    font-size: 1.1rem;
}

button {
    background-color: var(--accent-color);
    color: #000;
    border: none;
    padding: 1rem 1.5rem;
    font-size: 1.1rem;
    font-weight: bold;
    border-radius: 4px;
    cursor: pointer;
    width: 100%;
    margin-top: 1rem;
    transition: background-color 0.2s;
}

button:hover {
    background-color: #a370db;
}

button:focus {
    outline: none;
}

:focus-visible {
    outline: 3px solid var(--text-color);
    outline-offset: 4px;
}

@media (forced-colors: active) {
    .form-field {
        border: 2px solid CanvasText;
    }
    button {
        border: 2px solid ButtonBorder;
    }
    :focus-visible {
        outline: 3px solid Highlight;
    }
}
