 document.addEventListener('DOMContentLoaded', () => {
     const quizForm = document.getElementById('quiz-form');
     const feedback = document.getElementById('feedback');

     const correctAnswers = {
         q1: ['cpp', 'rust', 'go'],
         q2: ['js', 'php', 'ruby'],
         q3: ['c', 'rust', 'cpp']
     };

     quizForm.addEventListener('submit', (e) => {
         e.preventDefault();

         const questions = ['q1', 'q2', 'q3'];
         let firstInvalid = null;
         let isValid = true;

         // Validation
         questions.forEach(qKey => {
             const checked = quizForm.querySelectorAll(`input[name="${qKey}"]:checked`);
             const errorMsg = document.getElementById(`${qKey}-error`);

             if (checked.length === 0) {
                 errorMsg.hidden = false;
                 isValid = false;
                 if (!firstInvalid) firstInvalid = quizForm.querySelector(`input[name="${qKey}"]`);
             } else {
                 errorMsg.hidden = true;
             }
         });

         if (!isValid) {
             firstInvalid.focus();
             return;
         }

         let score = 0;
         const totalQuestions = Object.keys(correctAnswers).length;

         Object.keys(correctAnswers).forEach(qKey => {
             const selectedOptions = Array.from(quizForm.querySelectorAll(`input[name="${qKey}"]:checked`))
                 .map(cb => cb.value);

             const correctSet = correctAnswers[qKey];

             // Check if selected options match correct answers exactly
             const isCorrect = selectedOptions.length === correctSet.length &&
                 selectedOptions.every(val => correctSet.includes(val));

             if (isCorrect) {
                 score++;
             }
         });

         displayFeedback(score, totalQuestions);
     });

     function displayFeedback(score, total) {
         feedback.innerHTML = '';
         const percentage = (score / total) * 100;

         let message = `You scored ${score} out of ${total} (${percentage.toFixed(0)}%). `;

         if (score === total) {
             message += "Perfect! You really know your languages!";
             feedback.className = 'success';
         } else if (score > 0) {
             message += "Good job! Keep learning.";
             feedback.className = 'success';
         } else {
             message += "Better luck next time! Try again.";
             feedback.className = 'error';
         }

         feedback.textContent = message;
         // Scroll to feedback for visibility if needed, or just let aria-live handle it
         feedback.scrollIntoView({ behavior: 'smooth' });
     }
 });

')

